/**
 * Package cls defines Crum class constants.
 *
 * NOTE: Keep the content of this file sorted in alphabetical order.
 */

/**
 * ABBREVIATION is the class of the abbreviation that a tooltip explains,
 * introducing its own interpretation. Contrast with `CLUE`.
 */
export const ABBREVIATION = 'abbreviation';

export const AMHARIC = 'amharic';
/**
 * ANNOTATION is the class of a Crum Wiki annotation.
 */
export const ANNOTATION = 'annotation';
export const ANTECEDENT = 'antecedent';
export const ARABIC = 'arabic';
export const ARAMAIC = 'aramaic';
/**
 * BIBL is the class of the bibliography of a KELLIA sense.
 */
export const BIBL = 'bibl';
/**
 * BIBLE represents a Biblical reference in the Crum Wiki.
 */
export const BIBLE = 'bible';
/**
 * BULLET is the class of a bullet point bullet in the Crum Wiki.
 */
export const BULLET = 'bullet';
export const CATEGORIES = 'categories';
/**
 * CLUE is the class of a token of the citation location — a volume number, a
 * postfix siglum — highlighted inside a source's title or description, so the
 * user can locate the citation more quickly. Unlike an `ABBREVIATION`, a clue
 * belongs to the surrounding text; it introduces nothing.
 */
export const CLUE = 'clue';
export const COPTIC = 'coptic';
export const COPY = 'copy';
export const ADDENDUM = 'addendum';
export const CRUM_PAGE = 'crum-page';
export const DEMOTIC = 'demotic';
export const DEV_MODE_NOTE = 'dev-mode-note';
/**
 * DIALECT is the class of a dialect code, be it in Marcion or Wiki.
 */
export const DIALECT = 'dialect';
export const DRV_KEY = 'drv-key';
export const DRV_LINK = 'drv-link';
export const ENTRY = 'entry';
/**
 * ETYM_NOTE is the class of a note in the etymology of a KELLIA word.
 */
export const ETYM_NOTE = 'etym-note';
export const EXPLAIN_CHECKBOX = 'explain-checkbox';
export const EXPLANATORY = 'explanatory';
export const EXPLANATORY_KEY = 'explanatory-key';
export const FINE_PRINT = 'fine-print';
/**
 * FOLIO is the class of a Crum page's worth of Wiki content: a `.crum-page`
 * label followed by the entries printed on it.
 */
export const FOLIO = 'folio';
/**
 * FOOTNOTED is the class of a span wrapping text that has an attached
 * footnote. The footnote itself is carried by the inner `.mark` span in a
 * `data-footnote` attribute and rendered as a hover tooltip.
 */
export const FOOTNOTED = 'footnoted';
export const GLOSS = 'gloss';
/**
 * HEADING is the class of a the word starting a paragraph in the meaning of a
 * word.
 */
export const HEADING = 'heading';
export const HEADWORD = 'headword';
export const HEBREW = 'hebrew';
/** HIEROGLYPHIC is the class of Egyptian hieroglyphic text. */
export const HIEROGLYPHIC = 'hieroglyphic';
export const IBIDEM = 'ibidem';
export const INDEX_TABLE = 'index-table';
export const KASSER_PAGE = 'kasser-page';
/**
 * LANG is a language in a KELLIA meaning column (as of now, either "En", "Fr",
 * or "De").
 */
export const LANG = 'lang';
export const MARK = 'mark';
/**
 * ROMAN is the class of roman (non-italic) text in the meaning of a word.
 */
export const ROMAN = 'roman';
export const GREEK = 'greek';
/**
 * GREEK_REF is the class of the citations of the lexicons that list the Greek
 * lemma of a KELLIA loanword.
 */
export const GREEK_REF = 'greek-ref';
export const MANUAL = 'manual';
export const MEANING = 'meaning';
export const NAG_HAMMADI = 'nag-hammadi';
export const NAVIGATE = 'navigate';
/** OLD marks Coptic text that is rendered in the Old Coptic typeface. */
export const OLD = 'old';
export const PAGE = 'page';
export const QUALITY = 'quality';
export const QUIRE = 'quire';
/**
 * REFERENCE is the class of a reference in the Crum Wiki.
 */
export const REFERENCE = 'reference';
export const PART_OF_SPEECH = 'part-of-speech';
export const SEMICOLON = 'semicolon';
export const SENSES = 'senses';
export const SISTERS_TABLE = 'sisters-table';
export const SISTER_INDEX = 'sister-index';
export const SISTER_KEY = 'sister-key';
export const SISTER_VIEW = 'sister-view';
/**
 * SOURCE is the class of a KELLIA citation: the abbreviation of a cited work,
 * and the locations cited.
 */
export const SOURCE = 'source';
export const SPELLING = 'spelling';
/**
 * STACK renders two Coptic letters one above the other, as a ligature Crum
 * prints vertically. STACK_TOP and STACK_BOTTOM are its two halves.
 */
export const STACK = 'stack';
export const STACK_BOTTOM = 'stack-bottom';
export const STACK_TOP = 'stack-top';
/**
 * SUPER_ENTRY_TARGET is a sister in a KELLIA super entry. Its `data-key`
 * attribute holds the ID of the sister's entry.
 */
export const SUPER_ENTRY_TARGET = 'super-entry-target';
export const TAB = 'tab';
/**
 * TITLE is the class of the title of a cited work, appearing either in a
 * source's own title or inside its description. It is what `bib.yaml` marks
 * with `*…*`.
 */
export const TITLE = 'title';
export const TYPE = 'type';
export const WIKI = 'wiki';
export const WORD = 'word';
/**
 * XR_TARGET is the word that a KELLIA cross-reference refers to.
 */
export const XR_TARGET = 'xr-target';
